function EXTRA(R,ICON){
 /* hook: a city plan seen from above: two big blocks, rows of houses, and roads between */
 ICON.vzCity=(x,y)=>{let s=`<rect x="${x-220}" y="${y-200}" width="440" height="400" rx="18" fill="#EEF2E6" stroke="${VZL}" stroke-width="3"/>`;
  s+=`<rect x="${x-220}" y="${y-18}" width="440" height="36" fill="#C7CCD6"/><rect x="${x-18}" y="${y-200}" width="36" height="400" fill="#C7CCD6"/>`+vzL(x-210,y,x+210,y,WHT,3,{dash:'14 10'})+vzL(x,y-190,x,y+190,WHT,3,{dash:'14 10'});
  s+=vzB(x-200,y-184,160,150,{fill:VZS,st:BLU,rx:10})+vzT(x-120,y-100,'stadium',{fs:24,a:'middle'})+vzB(x+36,y-184,170,110,{fill:VZO,st:ORG,rx:10})+vzT(x+121,y-122,'mall',{fs:24,a:'middle'});
  for(let r=0;r<3;r++)for(let k=0;k<4;k++){s+=`<path d="M${x-196+k*40} ${y+60+r*46}l14 -14l14 14v20h-28z" fill="${WHT}" stroke="${GRN}" stroke-width="2.5"/>`;s+=`<path d="M${x+40+k*40} ${y+60+r*46}l14 -14l14 14v20h-28z" fill="${WHT}" stroke="${GRN}" stroke-width="2.5"/>`}
  return s+vzT(x+121,y-46,'roads need room',{fs:22,a:'middle',fill:VZM})};
 /* recap 1: the floorplan with whitespace */
 ICON.vzFloor=(x,y)=>vzCore(x-150,y-150,300,300,[[8,8,90,170],[202,8,90,120],[202,200,90,92],[8,236,90,56]],[110,190,24,280,24])+vzT(x,y+182,'75.6 % used',{fs:26,a:'middle',fw:800,fill:BLU});
 /* recap 2: a core in its wrapper, on the bus, with its address */
 ICON.vzIP=(x,y)=>vzB(x-190,y-130,250,190,{fill:VZG,st:GRN,dash:'10 7',rx:12})+vzB(x-160,y-100,140,130,{fill:WHT,st:BLU,rx:8})+vzT(x-90,y-26,'IP core',{fs:26,a:'middle',fw:800})+
  vzB(x-6,y-60,50,60,{fill:VZO,st:ORG,rx:6})+vzT(x+19,y-22,'regs',{fs:18,a:'middle'})+vzL(x+60,y-35,x+110,y-35,INK,4)+`<rect x="${x+110}" y="${y-150}" width="22" height="260" rx="11" fill="${VZS}" stroke="${BLU}" stroke-width="3"/>`+
  vzT(x-60,y+120,'0x4000_0000',{fs:26,a:'middle',mono:1,fill:ORG});
 /* recap 3: the smallest limit wins */
 ICON.vzFit=(x,y)=>{let s='';[['LUTs',6,ORG],['DSP',5,GRN],['BRAM',5,GRN]].forEach(([t,n,col],i)=>{const yy=y-150+i*92;s+=vzT(x-215,yy+36,t,{fs:28,fw:800})+[...Array(n)].map((_,k)=>`<rect x="${x-100+k*54}" y="${yy}" width="48" height="48" rx="7" fill="${col===GRN?VZG:VZO}" stroke="${col}" stroke-width="3"/>`).join('')});
  return s+vzL(x-100+5*54-3,y-170,x-100+5*54-3,y+140,RED,4,{dash:'10 7'})+vzT(x,y+184,'min = 5 cores',{fs:30,a:'middle',fw:800,fill:GRN})};
}
